import{_ as i,a0 as s,w as p,s as u,I as n,x as e,a1 as r,A as o,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"嘗試、學習、修改：新 IT 領導者的代碼 | LCTT x X-CMD","titleTemplate":false,"description":"嘗試、學習、修改：新 IT 領導者的代碼 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"嘗試、學習、修改：新 IT 領導者的代碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"嘗試、學習、修改：新 IT 領導者的代碼 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180306 Try, learn, modify- The new IT leader-s code","title":"嘗試、學習、修改：新 IT 領導者的代碼","tag":"201808","desc":""},"relativePath":"201808/20180306 Try, learn, modify- The new IT leader-s code.md","filePath":"[post].md"}'),d={name:"201808/20180306 Try, learn, modify- The new IT leader-s code.md"};function m(T,t,f,g,y,C){const l=s("Link");return p(),u("div",null,[t[26]||(t[26]=n("h1",{id:"嘗試、學習、修改-新-it-領導者的代碼",tabindex:"-1"},[e("嘗試、學習、修改：新 IT 領導者的代碼 "),n("a",{class:"header-anchor",href:"#嘗試、學習、修改-新-it-領導者的代碼","aria-label":"Permalink to “嘗試、學習、修改：新 IT 領導者的代碼”"},"​")],-1)),t[27]||(t[27]=n("blockquote",null,[n("p",null,"隨着創新步伐的增加, 長期規劃變得越來越困難。讓我們重新思考一下我們對變化的反應方式。")],-1)),t[28]||(t[28]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/ship_wheel_gear_devops_kubernetes.png?itok=xm4a74Kv",alt:""})],-1)),t[29]||(t[29]=n("p",null,"幾乎每一天，新的技術發展都可能會動搖那些甚至最複雜、最完善的商業計劃。組織經常發現自己需要不斷努力適應新的環境，這導致了他們對未來規劃的轉變。",-1)),n("p",null,[t[2]||(t[2]=e("根據 CompTIA 2017 年的",-1)),r(l,{href:"https://www.cio.com/article/3246027/enterprise-architecture/the-death-of-long-term-it-planning.html?upd=1515780110970"},{default:o(()=>[...t[0]||(t[0]=[e("研究",-1)])]),_:1}),t[3]||(t[3]=e("，目前只有 34% 的公司正在制定超過 12 個月的 IT 架構計劃。從長期計劃轉變的一個原因是：商業環境變化如此之快，以至於幾乎不可能進一步規劃未來。",-1)),r(l,{href:"https://www.cio.com/article/3246027/enterprise-architecture/the-death-of-long-term-it-planning.html?upd=1515780110970"},{default:o(()=>[...t[1]||(t[1]=[e("CIO.com 説道",-1)])]),_:1}),t[4]||(t[4]=e("，“如果你的公司正視圖制定一項將持續五到十年的計劃，那就忘了它。”",-1))]),t[30]||(t[30]=a('<p>我聽過來自世界各地無數客户和合作夥伴的類似聲明：技術創新正以一種前所未有的速度發生着。</p><p>其結果是長期規劃已不復存在。如果我們要在這個新世界取得成功，我們需要以不同的方式思考我們運營組織的方式。</p><h3 id="計劃是怎麼死的" tabindex="-1">計劃是怎麼死的 <a class="header-anchor" href="#計劃是怎麼死的" aria-label="Permalink to “計劃是怎麼死的”">​</a></h3><p>正如我在《<ruby>開放式組織<rt>The Open Organization</rt></ruby>》中寫的那樣，傳統經營組織針對工業經濟進行了優化。他們採用等級結構和嚴格規定的流程，以實現地位競爭優勢。要取得成功，他們必須確定他們想要實現的戰略地位。然後，他們必須制定並規劃實現目標的計劃，並以最有效的方式執行這些計劃，通過協調活動和推動合規性。</p><p>管理層的職責是優化這一過程：計劃、規定、執行。包括：讓我們想像一個有競爭力的優勢地位；讓我們來配置組織以最終達成目標；然後讓我們通過確保組織的所有方面都遵守規定來推動執行。這就是我所説的“機械管理”，對於不同時期來説它都是一個出色的解決方案。</p><p>在當今動盪不定的世界中，我們預測和定義戰略位置的能力正在下降，因為變化的速度，新變量的引入速度正在加速。傳統的、長期的、戰略性規劃和執行不像以前那麼有效。</p><p>如果長期規劃變得如此困難，那麼規定必要的行為就更具有挑戰性。並且衡量對計劃的合規性幾乎是不可能的。</p><p>這一切都極大地影響了人們的工作方式。與過去傳統經營組織中的工人不同，他們為自己能夠重複行動而感到自豪，幾乎沒有變化和舒適的確定性 —— 今天的工人在充滿模糊性的環境中運作。他們的工作需要更大的創造力、直覺和批判性判斷 —— 更多的需要背離過去的“常規”，以適應當今的新情況。</p><p>以這種新方式工作對於價值創造變得更加重要。我們的管理系統必須專注於構建結構，系統和流程，以幫助創建積極主動的工人，他們能夠以快速和敏捷的方式進行創新和行動。</p><p>我們需要提出一個不同的解決方案來優化組織，以適應不同的經濟時代，從自下而上而不是自上而下開始。我們需要替換過去的三步驟 —— 計劃、規定、執行，以一種更適應當今動盪天氣的方法來取得成功 —— 嘗試、學習、修改。</p><h3 id="嘗試、學習、修改" tabindex="-1">嘗試、學習、修改 <a class="header-anchor" href="#嘗試、學習、修改" aria-label="Permalink to “嘗試、學習、修改”">​</a></h3><p>因為環境變化如此之快，而且幾乎沒有任何預警，並且因為我們需要採取的步驟不再提前計劃，我們需要培養鼓勵創造性嘗試和錯誤的環境，而不是堅持對五年計劃的忠誠。以下是以這種方式開始工作的一些暗示：</p>',12)),n("ul",null,[t[9]||(t[9]=n("li",null,[n("strong",null,"更短的計劃週期（嘗試）。"),e(" 管理者需要考慮的是他們可以快速嘗試的短期實驗，而不是在長期戰略方向上苦惱。他們應該尋求方法來幫助他們的團隊承擔計算風險，並利用他們掌握的數據來對最有利的路徑做出最好的猜測。他們可以通過降低開銷和讓團隊自由快速嘗試新方法來做到這一點。")],-1)),n("li",null,[t[6]||(t[6]=n("strong",null,"更高的失敗容忍度（學習）。",-1)),t[7]||(t[7]=e(" 更多的實驗頻率意味着更大的失敗機會。與傳統組織相比，富有創造力和有彈性的組織",-1)),r(l,{href:"https://opensource.com/open-organization/16/12/building-culture-innovation-your-organization"},{default:o(()=>[...t[5]||(t[5]=[e("對失敗的容忍度要高得多",-1)])]),_:1}),t[8]||(t[8]=e("。管理者應將失敗視為學習的機會，在他們的團隊正在運行的測試中收集反饋的時刻。",-1))]),t[10]||(t[10]=n("li",null,[n("strong",null,"更具適應性的結構（修改）。"),e(" 能夠輕鬆修改組織結構和戰略方向，以及在條件需要時願意這樣做，是確保組織能夠根據快速變化的環境條件發展的關鍵。管理者不能再拘泥於任何想法，因為這個想法證明自己對實現短期目標很有用。")],-1))]),t[31]||(t[31]=n("p",null,"如果長期計劃已經消亡，那麼就可以進行長期的短期實驗。嘗試，學習和修改，這是在不確定時期前進的最佳途徑。",-1)),n("p",null,[r(l,{href:"https://opensource.com/open-organization/resources/newsletter"},{default:o(()=>[...t[11]||(t[11]=[e("訂閲我們的每週實事通訊",-1)])]),_:1}),t[12]||(t[12]=e("以瞭解有關開源組織的更多信息。",-1))]),t[32]||(t[32]=n("hr",null,null,-1)),n("p",null,[t[14]||(t[14]=e("via: ",-1)),r(l,{href:"https://opensource.com/open-organization/18/3/try-learn-modify"},{default:o(()=>[...t[13]||(t[13]=[e("https://opensource.com/open-organization/18/3/try-learn-modify",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=e("作者：",-1)),r(l,{href:"https://opensource.com/users/remyd"},{default:o(()=>[...t[15]||(t[15]=[e("Jim Whitehurst",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),r(l,{href:"https://github.com/MjSeven"},{default:o(()=>[...t[16]||(t[16]=[e("MjSeven",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[23]||(t[23]=e("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),r(l,{href:"https://linux.cn/"},{default:o(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const b=i(d,[["render",m]]);export{w as __pageData,b as default};
